('original:science--life-science-biology--cell-transport-and-homeostasis:science--life-science-biology--cell-transport-and-homeostasis--17',1,'{"question":"A cell''s ion pump stops when its ATP supply is depleted. What does this suggest about the pump?","choices":["It is part of the cell wall","It performs only simple diffusion","It performs energy-dependent transport","It functions without a concentration gradient"],"answer":2,"explanation":""}'::jsonb,'7355ffb38c9aa99dc196f7f6489387d1','official',NULL,NULL,'Cell Transport and Homeostasis'),
('original:science--life-science-biology--cell-transport-and-homeostasis:science--life-science-biology--cell-transport-and-homeostasis--18',1,'{"question":"Body temperature rises, and a control system increases sweating. Which process does this illustrate?","choices":["Negative feedback responding to a temperature change","A feedforward response before any temperature change","Positive feedback amplifying a temperature change","A fixed response unrelated to temperature"],"answer":0,"explanation":""}'::jsonb,'b440dafc18aea8b3f3fc892f7127d790','official',NULL,NULL,'Cell Transport and Homeostasis'),
('original:science--life-science-biology--cell-transport-and-homeostasis:science--life-science-biology--cell-transport-and-homeostasis--19',1,'{"question":"A potato strip loses mass in a concentrated salt solution. What is the best explanation?","choices":["Salt drew water into the cells until they burst","Water moved out of its cells by osmosis","Water entered the cells by active transport","Salt prevented all water movement across membranes"],"answer":1,"explanation":""}'::jsonb,'8b0c09466c6e184cd4f4a6f2450f4b28','official',NULL,NULL,'Cell Transport and Homeostasis'),
('original:science--life-science-biology--cell-transport-and-homeostasis:science--life-science-biology--cell-transport-and-homeostasis--20',1,'{"question":"A substance crosses through a membrane channel from high to low concentration without ATP. Which label fits best?","choices":["Endocytosis","Exocytosis","Active transport","Facilitated diffusion"],"answer":3,"explanation":""}'::jsonb,'acecc285368240f5484a77b7d0992df2','official',NULL,NULL,'Cell Transport and Homeostasis'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--1',1,'{"question":"Which molecule is a major short-term energy-transfer carrier in cells?","choices":["DNA","Chlorophyll","Cellulose","ATP"],"answer":3,"explanation":""}'::jsonb,'9713fcfedc5c94f151100562bfa36349','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--2',1,'{"question":"What are the main starting materials in the usual summary equation for photosynthesis?","choices":["Glucose and oxygen","Carbon dioxide and water","Nitrogen and glucose","Oxygen and water"],"answer":1,"explanation":""}'::jsonb,'7976089a733a716237142392b34c7bb2','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--3',1,'{"question":"Which gas is a reactant in photosynthesis?","choices":["Nitrogen","Water vapor","Carbon dioxide","Oxygen"],"answer":2,"explanation":""}'::jsonb,'794402bf33bc8e3fe2c961514da211e2','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--4',1,'{"question":"Which gas is generally required for aerobic cellular respiration?","choices":["Oxygen","Nitrogen","Carbon dioxide","Hydrogen"],"answer":0,"explanation":""}'::jsonb,'39852fc69a53c11044c46afae6311fa4','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--5',1,'{"question":"Which sugar is commonly used to summarize the product of photosynthesis?","choices":["Fructose","Sucrose","Glucose","Lactose"],"answer":2,"explanation":""}'::jsonb,'920cde00143e72bd6951db68010bb518','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--6',1,'{"question":"Which pigment absorbs light for photosynthesis in green plants?","choices":["Hemoglobin","Keratin","Melanin","Chlorophyll"],"answer":3,"explanation":""}'::jsonb,'3ac8dd5ff527dc0089438f56c0dbe5aa','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--7',1,'{"question":"Where does glycolysis occur?","choices":["Cytoplasm","Golgi apparatus","Nucleus","Chloroplast thylakoid space"],"answer":0,"explanation":""}'::jsonb,'d23bcf10bfd679ab1a1c0aae48797a04','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--8',1,'{"question":"How do photosynthesis and respiration differ in their overall energy roles?","choices":["Both create energy from nothing","Photosynthesis stores energy in organic molecules; respiration transfers energy from them","Photosynthesis mainly releases energy from glucose","Respiration stores sunlight directly in chlorophyll"],"answer":1,"explanation":""}'::jsonb,'ee430d6bfe11f7c83a5b2134b31fcf9d','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--9',1,'{"question":"Why do plants need cellular respiration as well as photosynthesis?","choices":["They need usable cellular energy for many activities","Respiration is needed only when plants stop being green","Plant cells lack molecules that can store energy","Photosynthesis supplies ATP permanently to every plant cell"],"answer":0,"explanation":""}'::jsonb,'2a1e7753069b5c8210c750af9e645c29','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--10',1,'{"question":"What happens to matter during photosynthesis?","choices":["Carbon atoms are created from sunlight","Oxygen atoms change into carbon atoms","Atoms from reactants are rearranged into products","Water disappears without contributing atoms"],"answer":2,"explanation":""}'::jsonb,'0fca6db6d633206f812ede5888a9eff2','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--11',1,'{"question":"Why can a plant''s roots respire even though they usually do not photosynthesize?","choices":["Roots have no need for ATP","Roots can use sugars transported from photosynthetic tissues","Roots cannot contain mitochondria","Roots receive sunlight through soil particles"],"answer":1,"explanation":""}'::jsonb,'16c8e487e5f1f94b052ee8b88e2a3efc','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--12',1,'{"question":"What is the role of fermentation when oxygen is unavailable in some cells?","choices":["It produces more ATP than aerobic respiration","It turns carbon dioxide directly into glucose","It eliminates the need for glycolysis","It helps regenerate molecules needed for glycolysis to continue"],"answer":3,"explanation":""}'::jsonb,'8079b95004ad833756f6329172244bfa','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--13',1,'{"question":"Why can light intensity limit photosynthesis?","choices":["Light is required only to release heat","Light provides all the carbon atoms in sugar","Light replaces water in every photosynthetic reaction","Light supplies energy needed for the process"],"answer":3,"explanation":""}'::jsonb,'b4c4a24c27a24a529efc2f337549f89c','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--14',1,'{"question":"How can carbon dioxide availability affect a plant''s photosynthesis rate?","choices":["Too little carbon dioxide can limit carbon fixation","Carbon dioxide is only a waste product of photosynthesis","Carbon dioxide replaces the need for enzymes","More carbon dioxide guarantees unlimited photosynthesis"],"answer":0,"explanation":""}'::jsonb,'44b778cfa5afa0a6822298607634a71c','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--15',1,'{"question":"Why do many organisms depend indirectly on photosynthesis?","choices":["They all have chloroplasts in every cell","Photosynthesis supports food webs and contributes oxygen to the atmosphere","Animals obtain oxygen only by drinking water","Photosynthesis replaces all nutrient cycles"],"answer":1,"explanation":""}'::jsonb,'c397bc8f3c6f67f9ad493288f27fbd86','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--16',1,'{"question":"A leaf is kept in darkness, with other conditions suitable. Which statement is most accurate?","choices":["Photosynthesis speeds up while respiration stops","Both processes must cease immediately","Light-dependent photosynthesis stops, but respiration can continue","The leaf converts all its mitochondria into chloroplasts"],"answer":2,"explanation":""}'::jsonb,'4fba6769ade606cd3b7b7b6f87386fa4','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--17',1,'{"question":"A sealed chamber containing a green plant in strong light shows declining carbon dioxide. What explanation best fits?","choices":["The plant is doing no respiration","Photosynthesis is using carbon dioxide faster than respiration releases it","The chamber has begun creating carbon atoms","Only the roots are carrying out photosynthesis"],"answer":1,"explanation":""}'::jsonb,'e00f57cb90b0a6f5e3613f5f1b41a9d0','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--18',1,'{"question":"A pond receives little light for several days. Which effect is plausible for its photosynthetic organisms?","choices":["They can no longer perform any chemical reaction","Their photosynthesis becomes independent of water","Their cells no longer require nutrients","Their production of new organic material may decrease"],"answer":3,"explanation":""}'::jsonb,'1576be4ea274ddce92f3c292a1495659','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--19',1,'{"question":"Which pair best summarizes a matter connection between the two processes?","choices":["Photosynthesis produces organic molecules that can be used in respiration","Both processes consume glucose and oxygen","Photosynthesis uses only nitrogen; respiration releases only helium","Respiration produces sunlight that plants absorb"],"answer":0,"explanation":""}'::jsonb,'73c1637c2b6263165e632fac3d3db4b5','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--photosynthesis-and-cellular-respiration:science--life-science-biology--photosynthesis-and-cellular-respiration--20',1,'{"question":"An experiment compares a leaf''s carbon dioxide uptake at two temperatures while holding light constant. What must be considered when interpreting the result?","choices":["Temperature changes only the color of the container","Photosynthesis is unrelated to enzyme activity","Temperature can affect both photosynthesis and respiration","All plants have the same optimum temperature"],"answer":2,"explanation":""}'::jsonb,'a6649b082a5f81a8f76610fc7f46831d','official',NULL,NULL,'Photosynthesis and Cellular Respiration'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--1',1,'{"question":"What is a gene?","choices":["A DNA sequence contributing to a functional product","A cell structure that stores water","A protein that always determines one visible trait","A complete set of organs"],"answer":0,"explanation":""}'::jsonb,'b5f440026a5e66efa38e29d57d3a658b','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--2',1,'{"question":"What is an allele?","choices":["A collection of unrelated chromosomes","A type of ribosome","A version of a gene","A cell''s source of light energy"],"answer":2,"explanation":""}'::jsonb,'98f5650e31fffa79e5d2be7fefe02b5f','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--3',1,'{"question":"Which term describes an organism with two different alleles at a gene location?","choices":["Homozygous","Heterozygous","Dominant","Recessive"],"answer":1,"explanation":""}'::jsonb,'72d7044e3ddbab95ce637d2b591c46df','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--4',1,'{"question":"What is a genotype?","choices":["The conditions surrounding an organism","An organism''s visible appearance only","The number of cells in an organism","An organism''s genetic makeup at one or more locations"],"answer":3,"explanation":""}'::jsonb,'54ced036bf0b650e5ac12bc83ccf1854','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--5',1,'{"question":"What is a phenotype?","choices":["A chromosome copied before cell division","An observable characteristic resulting from genes and environment","A gamete''s entire energy supply","A single type of nitrogen base"],"answer":1,"explanation":""}'::jsonb,'b7f6109b9f953508560610ca47e390c4','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--6',1,'{"question":"In a simple complete-dominance model, when is a recessive phenotype expressed?","choices":["When both copies of the gene carry the recessive allele","Whenever one dominant allele is present","Only when the organism is male","Whenever the environment changes"],"answer":0,"explanation":""}'::jsonb,'3b588492cf49058e460c7f4f5924e4a0','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--7',1,'{"question":"Which cells carry hereditary information from parents through sexual reproduction?","choices":["Muscle cells","Skin cells","Nerve cells","Gametes"],"answer":3,"explanation":""}'::jsonb,'045bd5d3c7b4b800b645c4b065be64c9','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--8',1,'{"question":"Why do offspring in sexual reproduction receive alleles from two parents?","choices":["All their genes arise only after birth","Parents pass on only their acquired habits","Gametes from the parents combine at fertilization","Each parent contributes every chromosome twice"],"answer":2,"explanation":""}'::jsonb,'448a7c7cd0770067cbdd39a6069b95ae','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--9',1,'{"question":"What does a Punnett square show?","choices":["The order of all bases in a chromosome","The exact traits of every future child","How quickly a population grows","Possible allele combinations and their expected probabilities"],"answer":3,"explanation":""}'::jsonb,'3432cdfe99aaa04644e55f85073b7ca0','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--10',1,'{"question":"Why does dominant not mean more common in a population?","choices":["Dominant alleles cannot be inherited","Dominance describes expression in heterozygotes, not allele frequency","Dominant traits must always improve survival","Dominance measures the size of a chromosome"],"answer":1,"explanation":""}'::jsonb,'15d15b7157ded6143fd4cd837a021a62','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--11',1,'{"question":"What is incomplete dominance?","choices":["An allele cannot pass to offspring","Only one parent contributes hereditary information","A heterozygote has an intermediate phenotype in the stated model","Two different alleles are always expressed as separate traits"],"answer":2,"explanation":""}'::jsonb,'f5325357677e15d4f738e7eb3407b9b3','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--12',1,'{"question":"How can environment influence phenotype?","choices":["Conditions such as nutrition can affect how a trait develops","Genes stop affecting traits whenever conditions change","Environment necessarily changes every gene''s DNA sequence","All individuals in one environment have identical traits"],"answer":0,"explanation":""}'::jsonb,'55095826d0acbc4fe9e9f02d9b69942e','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--13',1,'{"question":"Why are many traits not predicted well by a one-gene Punnett square?","choices":["Punnett squares cannot describe gamete combinations","They are never inherited in any way","They involve multiple genes, environmental effects, or both","Every trait follows complete dominance"],"answer":2,"explanation":""}'::jsonb,'dc7d7202a7d9335599d7b62edf7dc357','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--14',1,'{"question":"What does segregation mean in basic Mendelian inheritance?","choices":["All alleles stay together in every gamete","The dominant allele prevents recessive gametes from forming","Alleles disappear whenever cells divide","The two alleles at a locus separate during gamete formation"],"answer":3,"explanation":""}'::jsonb,'97a1bdce7f244c5a96e994053fafb520','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--15',1,'{"question":"Why can siblings from the same parents have different inherited traits?","choices":["Different combinations of parental alleles can be inherited","Parents'' alleles are replaced after each birth","Each sibling belongs to a different biological species","Only the oldest child inherits chromosomes"],"answer":0,"explanation":""}'::jsonb,'de0298d3681e9883cd35b415839084e0','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--16',1,'{"question":"Assume complete dominance: T is dominant to t. What phenotype is expected for Tt?","choices":["The recessive phenotype","The dominant phenotype","A phenotype determined only by age","No trait expression"],"answer":1,"explanation":""}'::jsonb,'1bb9566190d2b9e9bd1af13a92b1ed44','official',NULL,NULL,'Genetics and Inheritance'),
