('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--18',1,'{"question":"In a cross Aa × aa, what fraction of offspring is expected to be heterozygous?","choices":["One-fourth","Three-fourths","One-half","None"],"answer":2,"explanation":""}'::jsonb,'15c6d0b009930f697b72916e429e0094','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--19',1,'{"question":"Two heterozygous parents have three children with a dominant phenotype. What is the correct conclusion about a fourth child in a simple Mendelian model?","choices":["The fourth must have the recessive phenotype","Each fertilization still has its own inheritance probabilities","The fourth cannot inherit a recessive allele","The parents'' genotypes have changed to homozygous dominant"],"answer":1,"explanation":""}'::jsonb,'0ef6fb057eb3b67631c0d0ddeb725ad7','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--genetics-and-inheritance:science--life-science-biology--genetics-and-inheritance--20',1,'{"question":"A trait changes with diet even among organisms sharing the same relevant genotype. What does this support?","choices":["The trait cannot have any genetic component","The diet has necessarily changed every DNA sequence","The organisms must have different parents","Environmental conditions can affect phenotype"],"answer":3,"explanation":""}'::jsonb,'81e0573e7f8d91a8820ddc4116a1b6c3','official',NULL,NULL,'Genetics and Inheritance'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--1',1,'{"question":"What is biological evolution?","choices":["A change in one organism''s habits during life","A change in inherited population characteristics across generations","An increase in an individual''s body size","A daily change in local weather"],"answer":1,"explanation":""}'::jsonb,'0cf951395e73e4cb7875e504db9a7c2f','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--2',1,'{"question":"What is natural selection?","choices":["Differential reproductive success associated with heritable traits","The deliberate choice of mates by scientists only","A process in which organisms request useful mutations","The inheritance of every acquired behavior"],"answer":0,"explanation":""}'::jsonb,'ec2ea6490af79ffb5693d464f17cb645','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--3',1,'{"question":"What is an adaptation in evolutionary biology?","choices":["Any injury sustained during an organism''s life","Any temporary change in an organism''s mood","A trait guaranteed to help in every environment","A heritable feature that improves success in a particular environment"],"answer":3,"explanation":""}'::jsonb,'c19f0d49c4bcb6678a20348f15d117da','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--4',1,'{"question":"What can produce new alleles in a population?","choices":["Exercise","Seasonal migration","Mutation","Competition alone"],"answer":2,"explanation":""}'::jsonb,'efd82d952bf2c1766d62b31c41c61d99','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--5',1,'{"question":"What does fitness refer to in evolutionary biology?","choices":["Freedom from all disease","Physical strength in every setting","An individual''s maximum running speed","Reproductive contribution to later generations"],"answer":3,"explanation":""}'::jsonb,'d56bb1de236f892c57da6e3dcbd38b13','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--6',1,'{"question":"Which process involves humans choosing organisms with desired traits to reproduce?","choices":["Genetic drift","Artificial selection","Natural selection","Gene flow"],"answer":1,"explanation":""}'::jsonb,'fabf801fff1c744759ca95bb213bdcd9','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--7',1,'{"question":"What is a fossil?","choices":["Preserved remains or traces of past life","A modern reconstruction based on ancient remains","Any living organism that is very old","A rock containing no evidence of an organism"],"answer":0,"explanation":""}'::jsonb,'3a30172b6a12e06bf86174dd7cabbdc0','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--8',1,'{"question":"Why must a trait be heritable for selection on that trait to drive evolutionary change?","choices":["All inherited traits are equally beneficial","Acquired injuries always alter gamete DNA","The trait''s effects must be passed into later generations","Selection acts only on traits absent from parents"],"answer":2,"explanation":""}'::jsonb,'8d96bf0ddffab704bae3d7815a2471d4','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--9',1,'{"question":"Why do populations, rather than individual organisms, evolve through natural selection?","choices":["Evolution requires every individual to change in the same way","Each organism deliberately rewrites its genes as needed","Inherited trait frequencies change as generations replace one another","Individuals never vary in inherited traits"],"answer":2,"explanation":""}'::jsonb,'b4fa6973a0ca15fb6d7d2c473e3600c3','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--10',1,'{"question":"How can similar underlying limb structures in different vertebrates support evolution?","choices":["They prove the animals have identical diets","They exclude any role for inheritance","They show every vertebrate evolved at the same time","They can provide evidence of common ancestry"],"answer":3,"explanation":""}'::jsonb,'c029c7780936dd5aae4d889ad7e33bdf','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--11',1,'{"question":"Why can a trait beneficial in one habitat be less useful in another?","choices":["Mutation stops whenever habitats differ","The trait''s effects depend on environmental conditions","All habitats impose identical survival demands","A beneficial trait must always increase body size"],"answer":1,"explanation":""}'::jsonb,'64c9ff00750acdfa0930cfef5f271832','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--12',1,'{"question":"What is genetic drift?","choices":["Random changes in allele frequencies, especially influential in small populations","The formation of alleles because organisms need them","The planned movement of animals between parks","The directed copying of only dominant genes"],"answer":0,"explanation":""}'::jsonb,'b99b3ed1f45509f5b149971a02544e1d','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--13',1,'{"question":"How does gene flow affect populations?","choices":["Movement and reproduction can transfer alleles between populations","It requires every individual to have the same genotype","It changes rocks into fossils","It prevents all inherited variation"],"answer":0,"explanation":""}'::jsonb,'e6ad9e3068426ae048124758ef1d3b18','official',NULL,NULL,'Evolution and Natural Selection'),
('original:science--life-science-biology--evolution-and-natural-selection:science--life-science-biology--evolution-and-natural-selection--14',1,'{"question":"Why does antibiotic use select for resistant bacteria?","choices":["Antibiotics intentionally produce the same helpful mutation in every bacterium","Bacteria stop reproducing when resistance develops","Resistant bacteria may survive treatment and reproduce more successfully","Resistance is always caused by a patient''s behavior"],"answer":2,"explanation":""}'::jsonb,'21f746eb455bce08b372baac8e19c8ad','official',NULL,NULL,'Evolution and Natural Selection'),
