('original:science--life-science-biology--biodiversity-and-conservation:science--life-science-biology--biodiversity-and-conservation--13',1,'{"question":"Why can conservation planning use both richness and abundance data?","choices":["Species richness measures the population size of each species","Abundance data show habitat quality without species information","Equal richness means two communities have equal evenness","Species counts alone omit population sizes and evenness"],"answer":3,"explanation":""}'::jsonb,'b5daf274829827ec9d1b2981044e4c99','official',NULL,NULL,'Biodiversity and Conservation'),
('original:science--life-science-biology--biodiversity-and-conservation:science--life-science-biology--biodiversity-and-conservation--14',1,'{"question":"Why might a small isolated population face genetic risks?","choices":["Isolation creates unlimited new alleles","Limited gene flow and chance allele loss can reduce variation","Small populations never experience drift","All recessive alleles disappear automatically"],"answer":1,"explanation":""}'::jsonb,'34c28421468038d8a91bddd29640aa1a','official',NULL,NULL,'Biodiversity and Conservation'),
('original:science--life-science-biology--biodiversity-and-conservation:science--life-science-biology--biodiversity-and-conservation--15',1,'{"question":"Why should restoration success be monitored over time?","choices":["The first year''s results establish permanent recovery","Recovery is measured only by the number of seedlings planted","Recovery can vary and require revised management","Management choices cannot influence later outcomes"],"answer":2,"explanation":""}'::jsonb,'d004113f10a9ea5ab262ac8795174bd6','official',NULL,NULL,'Biodiversity and Conservation'),
