('original:science--life-science-biology--microorganisms-and-viruses:science--life-science-biology--microorganisms-and-viruses--5',1,'{"question":"What is binary fission?","choices":["Fusion of two gametes","Division of one prokaryotic cell into two cells","Assembly of a virus outside all cells","Formation of a fungal fruiting body"],"answer":1,"explanation":""}'::jsonb,'12814404b9c5f744a934ae7d4128da74','official',NULL,NULL,'Microorganisms and Viruses'),
('original:science--life-science-biology--microorganisms-and-viruses:science--life-science-biology--microorganisms-and-viruses--6',1,'{"question":"What is a pathogen?","choices":["An organism that always improves host health","A community of microbes in one habitat","A chemical messenger produced by nerve cells","An agent capable of causing disease"],"answer":3,"explanation":""}'::jsonb,'628220db81bb711eccd29d45b317bdeb','official',NULL,NULL,'Microorganisms and Viruses'),
('original:science--life-science-biology--microorganisms-and-viruses:science--life-science-biology--microorganisms-and-viruses--7',1,'{"question":"What is a microbiome?","choices":["A community of microorganisms in a particular environment","The genetic material of one microorganism","A particular habitat''s nonliving conditions","A group containing only disease-causing viruses"],"answer":0,"explanation":""}'::jsonb,'c70194ce37259654cc9a20075f81d9ec','official',NULL,NULL,'Microorganisms and Viruses'),
('original:science--life-science-biology--microorganisms-and-viruses:science--life-science-biology--microorganisms-and-viruses--8',1,'{"question":"Why are not all microorganisms harmful?","choices":["Disease-causing and beneficial microbes have identical ecological roles","Only multicellular organisms recycle nutrients","Many support processes such as decomposition or nutrient cycling","All microbial interactions reduce other organisms'' survival"],"answer":2,"explanation":""}'::jsonb,'dfbec74bdda82a98c59574f4135ae8ac','official',NULL,NULL,'Microorganisms and Viruses'),
('original:science--life-science-biology--microorganisms-and-viruses:science--life-science-biology--microorganisms-and-viruses--9',1,'{"question":"Why can bacteria reproduce without a host cell while viruses cannot reproduce independently?","choices":["Viruses contain the same complete cellular machinery as bacteria","Bacteria reproduce only inside the same hosts as viruses","Viruses obtain all energy through independent photosynthesis","Bacteria have cellular machinery; viruses rely on host machinery"],"answer":3,"explanation":""}'::jsonb,'30ffda4c4ad43f4696efa68466c170b2','official',NULL,NULL,'Microorganisms and Viruses'),
('original:science--life-science-biology--microorganisms-and-viruses:science--life-science-biology--microorganisms-and-viruses--10',1,'{"question":"How can microbes contribute to nitrogen cycling?","choices":["All microbes perform the same nitrogen transformation","Some transform nitrogen into forms other organisms can use","Only plant roots can transform atmospheric nitrogen","Microbes use nitrogen but cannot change its chemical form"],"answer":1,"explanation":""}'::jsonb,'197a6e79c3f34bca1f6cced322a51602','official',NULL,NULL,'Microorganisms and Viruses'),
