('original:science--life-science-biology--microorganisms-and-viruses:science--life-science-biology--microorganisms-and-viruses--12',1,'{"question":"Why can decomposer microorganisms affect soil fertility?","choices":["They break down material and return nutrients to usable pools","They store all released nutrients where plants cannot use them","They slow every chemical process in soil","They consume organic matter without returning any nutrients"],"answer":0,"explanation":""}'::jsonb,'93636335cd471bec50a440df75ea67e4','official',NULL,NULL,'Microorganisms and Viruses'),
