('original:science--life-science-biology--nervous-and-endocrine-systems:science--life-science-biology--nervous-and-endocrine-systems--12',1,'{"question":"What role do motor neurons commonly serve?","choices":["Detect every blood chemical directly","Filter waste from blood","Carry commands to effectors such as muscles","Carry only information from skin toward the brain"],"answer":2,"explanation":""}'::jsonb,'d006455c69f9aa1df20d4bd0839fff4a','official',NULL,NULL,'Nervous and Endocrine Systems'),
('original:science--life-science-biology--nervous-and-endocrine-systems:science--life-science-biology--nervous-and-endocrine-systems--13',1,'{"question":"How does myelin help many axons?","choices":["It slows conduction so each signal remains longer","It produces the hormones carried by the neuron","It supports faster impulse conduction","It acts as the receptor for every neurotransmitter"],"answer":2,"explanation":""}'::jsonb,'aa3837cebdcd26d39295040bd3aa5078','official',NULL,NULL,'Nervous and Endocrine Systems'),
