('original:science--physical-science-chemistry--periodic-table-and-trends:science--physical-science-chemistry--periodic-table-and-trends--10',1,'{"question":"How does electronegativity generally change from left to right across a period, excluding noble-gas complications?","choices":["It generally increases","It depends only on density","It steadily decreases","It is identical for every element"],"answer":0,"explanation":""}'::jsonb,'e92ea5dd2614429ba17535be3b68f46d','official',NULL,NULL,'Periodic Table and Trends'),
('original:science--physical-science-chemistry--periodic-table-and-trends:science--physical-science-chemistry--periodic-table-and-trends--11',1,'{"question":"Why are noble gases relatively unreactive under many ordinary conditions?","choices":["They contain no charged particles","Their outer electron shells are filled","Their nuclei cannot attract electrons","They have no electron shells"],"answer":1,"explanation":""}'::jsonb,'7fb014bd7cd02b2bcbe3309397251abb','official',NULL,NULL,'Periodic Table and Trends'),
('original:science--physical-science-chemistry--periodic-table-and-trends:science--physical-science-chemistry--periodic-table-and-trends--12',1,'{"question":"What is ionization energy?","choices":["The energy released when water freezes","Energy needed to remove a neutron from every isotope","Energy required to remove an electron from a gaseous atom or ion","Energy stored only in a metal''s crystal shape"],"answer":2,"explanation":""}'::jsonb,'10f4be4b6aad7a78676716f6d7eb379e','official',NULL,NULL,'Periodic Table and Trends'),
('original:science--physical-science-chemistry--periodic-table-and-trends:science--physical-science-chemistry--periodic-table-and-trends--13',1,'{"question":"Why do alkali metals commonly form +1 ions?","choices":["They gain two electrons in ordinary compounds","They gain one proton during bonding","They lose one neutron during every reaction","They can lose one outer electron"],"answer":3,"explanation":""}'::jsonb,'5a3c7a985c6e0024eeef246773e9b6d3','official',NULL,NULL,'Periodic Table and Trends'),
('original:science--physical-science-chemistry--periodic-table-and-trends:science--physical-science-chemistry--periodic-table-and-trends--14',1,'{"question":"What does the periodic table reveal beyond a list of element names?","choices":["Exact weather conditions during every reaction","The number of molecules in every sample","Patterns in atomic structure and properties","The temperature of all substances at room pressure"],"answer":2,"explanation":""}'::jsonb,'621c43a9262d9590ecbe3bfa9d54efa9','official',NULL,NULL,'Periodic Table and Trends'),
('original:science--physical-science-chemistry--periodic-table-and-trends:science--physical-science-chemistry--periodic-table-and-trends--15',1,'{"question":"How do metalloids differ from typical metals and typical nonmetals?","choices":["They have some properties associated with each group","They have no atomic number","They occur only as radioactive gases","They are mixtures of two elements"],"answer":0,"explanation":""}'::jsonb,'61f22fb684bc2d28c4b94fa1ae4a1732','official',NULL,NULL,'Periodic Table and Trends'),
('original:science--physical-science-chemistry--periodic-table-and-trends:science--physical-science-chemistry--periodic-table-and-trends--16',1,'{"question":"An element is in the same group as chlorine. Which property is most reasonably expected?","choices":["It has exactly 17 protons","It has chemical similarities associated with the group''s valence pattern","It has the same mass as chlorine","It must be a gas at room temperature"],"answer":1,"explanation":""}'::jsonb,'fd60cccc00c2b0e0335bb65f00bcbbc6','official',NULL,NULL,'Periodic Table and Trends')
