('original:science--physical-science-chemistry--chemical-bonding:science--physical-science-chemistry--chemical-bonding--3',1,'{"question":"Which electrons are most directly involved in ordinary chemical bonding?","choices":["Only electrons closest to every nucleus","Only electrons in neutrons","Every electron equally in every bond","Valence electrons"],"answer":3,"explanation":""}'::jsonb,'a7fa68d6932b10ec94474add1ca7c973','official',NULL,NULL,'Chemical Bonding'),
