('original:science--physical-science-chemistry--chemical-bonding:science--physical-science-chemistry--chemical-bonding--7',1,'{"question":"What is a major feature of metallic bonding?","choices":["One separate pair of electrons locked between each ion only","Covalent molecules floating between metal atoms","Delocalized electrons associated with many metal atoms","Oppositely charged nonmetal molecules alternating in layers"],"answer":2,"explanation":""}'::jsonb,'30574feab0764a9f7fe91d27b6ba2bfd','official',NULL,NULL,'Chemical Bonding'),
