('original:science--physical-science-chemistry--states-of-matter:science--physical-science-chemistry--states-of-matter--17',1,'{"question":"Dry ice disappears without leaving a liquid puddle under ordinary room conditions. Which change occurs?","choices":["Condensation","Sublimation","Freezing","Deposition"],"answer":1,"explanation":""}'::jsonb,'752a50c98c6de462176354356fb8bf04','official',NULL,NULL,'States of Matter'),
