('original:science--physical-science-chemistry--matter-properties-and-changes:science--physical-science-chemistry--matter-properties-and-changes--8',1,'{"question":"Why does melting generally leave a substance''s chemical identity unchanged?","choices":["Its atoms lose all electrons","Its particles rearrange without becoming a different substance","Its elements change during every melting event","Its mass must disappear"],"answer":1,"explanation":""}'::jsonb,'c3f705c36c1ffb38d3851b6a5e2aa1d4','official',NULL,NULL,'Matter Properties and Changes'),
