('original:science--physical-science-chemistry--elements-compounds-and-mixtures:science--physical-science-chemistry--elements-compounds-and-mixtures--14',1,'{"question":"Why does distillation work for suitable liquid mixtures?","choices":["Every component has exactly the same boiling point","Heating necessarily creates new elements","Components have different vaporization and condensation behavior","The heavier liquid always vanishes first"],"answer":2,"explanation":""}'::jsonb,'ba87d01020aa99f8f5a2737b51af59ce','official',NULL,NULL,'Elements Compounds and Mixtures'),
