('original:science--earth-space-science--plate-tectonics:science--earth-space-science--plate-tectonics--18',1,'{"question":"A GPS station moves 3 centimeters west each year. What does this measurement support?","choices":["The station''s continent is motionless","Earth''s rotation is slowing by 3 centimeters yearly","The plate beneath the station is moving","The mantle beneath the station is entirely liquid"],"answer":2,"explanation":""}'::jsonb,'1230b80409bbcbf34e5e4f203be8b020','official',NULL,NULL,'Plate Tectonics'),
('original:science--earth-space-science--plate-tectonics:science--earth-space-science--plate-tectonics--19',1,'{"question":"Continental crust begins stretching and breaking along a divergent boundary. Which feature may develop?","choices":["A deep subduction trench","A folded collision mountain belt","A transform boundary with no separation","A rift valley"],"answer":3,"explanation":""}'::jsonb,'603092badda744143a0aca9f6bab4a59','official',NULL,NULL,'Plate Tectonics'),
('original:science--earth-space-science--plate-tectonics:science--earth-space-science--plate-tectonics--20',1,'{"question":"Which explanation best connects plate movement with Earth''s internal energy?","choices":["Surface winds supply the main force for plate motion","Solar heating makes whole plates slide toward the equator","Internal heat supports mantle motion, while gravity helps drive processes such as slab pull","Tidal forces alone account for all long-term plate motion"],"answer":2,"explanation":""}'::jsonb,'e666ba87107a2c76f4987b882e598edc','official',NULL,NULL,'Plate Tectonics'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--1',1,'{"question":"Which rock type forms when magma or lava cools and solidifies?","choices":["Unconsolidated sediment","Sedimentary","Metamorphic","Igneous"],"answer":3,"explanation":""}'::jsonb,'73869dbbd42fd4dadadfa69abbf88208','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--2',1,'{"question":"Which process commonly turns buried sediment into sedimentary rock?","choices":["Compaction and cementation","Melting and freezing","Evaporation and condensation","Faulting and subduction"],"answer":0,"explanation":""}'::jsonb,'aec5ab5c76d951146485d75deedc081b','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--3',1,'{"question":"What forms metamorphic rock?","choices":["Only surface weathering","Complete melting followed by cooling","Changes caused by heat and pressure without complete melting","Only the settling of grains in water"],"answer":2,"explanation":""}'::jsonb,'b0e9ac9e79a0b738d5b4b922d0767a40','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--4',1,'{"question":"What is weathering?","choices":["The breakdown of rock at or near Earth''s surface","Rock melting underground","The movement of sediment downstream","Sediment settling out of moving water"],"answer":0,"explanation":""}'::jsonb,'df7b8599e7590185448d34138db53861','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--5',1,'{"question":"What is erosion?","choices":["The crystallization of magma","The transport of weathered material","The compression of buried sediment","The formation of new minerals under heat"],"answer":1,"explanation":""}'::jsonb,'1bf4cc3752b1f6a54e097aadcef584e7','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--6',1,'{"question":"What is deposition?","choices":["Rock changing under pressure","Magma rising through the crust","Sediment being laid down","A mineral dissolving in water"],"answer":2,"explanation":""}'::jsonb,'369ee1d0dd2470130378f4e66323d682','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--7',1,'{"question":"In which rock type are fossils most commonly preserved?","choices":["Intrusive igneous","Extrusive igneous","Highly metamorphosed","Sedimentary"],"answer":3,"explanation":""}'::jsonb,'c87e3aa6ca79063a4855c146f8393756','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--8',1,'{"question":"Why does slowly cooling magma often produce large mineral crystals?","choices":["Large crystals form only under water","Slow cooling removes all minerals","Crystals have more time to grow","Pressure prevents crystals from growing"],"answer":2,"explanation":""}'::jsonb,'d3a14e850124a89431ae522bef5839fe','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--9',1,'{"question":"Why can lava cooled quickly at the surface produce fine-grained rock?","choices":["Crystals have little time to grow","The lava contains no dissolved elements","Weathering immediately removes all large crystals","Surface rocks cannot contain minerals"],"answer":0,"explanation":""}'::jsonb,'b167df7b68228f99f873bae2ad35286a','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--10',1,'{"question":"Why is the rock cycle described as a cycle rather than a single fixed sequence?","choices":["Each rock must pass through every step yearly","Rocks can change through several different pathways","All rocks eventually become the same mineral","Only igneous rocks can change type"],"answer":1,"explanation":""}'::jsonb,'5dd981cd13df7c3bd4d8429a05c8529e','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--11',1,'{"question":"What happens to a rock if it melts completely?","choices":["It becomes sediment immediately","It remains a metamorphic rock","It becomes a fossil-bearing rock","It becomes molten material that can later form igneous rock"],"answer":3,"explanation":""}'::jsonb,'b42b0b3fa1185ac3a97abfbd7052b126','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--12',1,'{"question":"How can a sedimentary rock become metamorphic rock?","choices":["By being moved downstream without changing","By cooling from lava at the surface","By experiencing sufficient heat and pressure while remaining solid","By breaking into loose sand alone"],"answer":2,"explanation":""}'::jsonb,'790b40ef71ca01167474a4b43d13540b','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--13',1,'{"question":"Why do many sedimentary rocks contain layers?","choices":["Sediments accumulate in successive deposits","Each layer records a separate volcanic eruption","Layers form only when rocks melt","Every layer must contain the same grain size"],"answer":0,"explanation":""}'::jsonb,'8c49e81576d918c2acc0a185bd9cf11b','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--14',1,'{"question":"Which process can chemically weather limestone?","choices":["Dry grains being pressed together","Sediment settling on a lake floor","Lava cooling around the limestone","Weakly acidic water dissolving minerals"],"answer":3,"explanation":""}'::jsonb,'aa02f6d2f2844d219016a77e4bfc4404','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--15',1,'{"question":"What makes a mineral different from a rock?","choices":["A mineral must contain fossils","A mineral has a characteristic composition and ordered crystal structure","A rock must consist of only one element","A mineral is always larger than a rock"],"answer":1,"explanation":""}'::jsonb,'c72c83a4f147ba0cca0d4c5797d27eca','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--16',1,'{"question":"A rock contains rounded pebbles cemented together. Which origin is most likely?","choices":["Magma cooling deep underground","Solid rock changing under intense heat","Lava cooling very quickly","Sediment being deposited and lithified"],"answer":3,"explanation":""}'::jsonb,'65d1759969f2af4c49644853efd8f188','official',NULL,NULL,'Rocks and the Rock Cycle')
