('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--17',1,'{"question":"A river slows as it enters a lake. What is likely to happen to some of its sediment?","choices":["It becomes metamorphic rock immediately","It turns directly into magma","It settles to the bottom","It moves faster because the water slows"],"answer":2,"explanation":""}'::jsonb,'b6be767beca4c278d4419eab08b38341','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--18',1,'{"question":"Two rocks have the same mineral composition, but one has much larger crystals. What is a reasonable explanation?","choices":["The larger-crystal rock cooled more quickly","The larger-crystal rock cooled more slowly","The smaller-crystal rock had no time to form any crystals","Crystal size alone proves the rocks contain different elements"],"answer":1,"explanation":""}'::jsonb,'79da933dd157f1f0bf9954eade780ef8','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--19',1,'{"question":"A sandstone is buried, heated, and transformed into quartzite without melting. Which transition occurred?","choices":["Sedimentary to metamorphic","Metamorphic to igneous","Igneous to sedimentary","Sediment directly to lava"],"answer":0,"explanation":""}'::jsonb,'3c3bb38b9456919e71826cde8015cc56','official',NULL,NULL,'Rocks and the Rock Cycle'),
('original:science--earth-space-science--rocks-and-the-rock-cycle:science--earth-space-science--rocks-and-the-rock-cycle--20',1,'{"question":"Which sequence can produce sedimentary rock from an exposed igneous rock?","choices":["Melting, cooling, and crystallization","Weathering, erosion, deposition, and lithification","Subduction, melting, and eruption","Heating, compression, and recrystallization only"],"answer":1,"explanation":""}'::jsonb,'1c774ac930db303b75777961cffcab3b','official',NULL,NULL,'Rocks and the Rock Cycle'),
