('original:science--earth-space-science--weather-and-the-water-cycle:science--earth-space-science--weather-and-the-water-cycle--10',1,'{"question":"What are most clouds made of?","choices":["Tiny liquid droplets or ice crystals","Visible water vapor gas alone","Only dry air under high pressure","Large raindrops resting without air movement"],"answer":0,"explanation":""}'::jsonb,'5ba2a74e8f9fb8cf9e1c357b492d82ba','official',NULL,NULL,'Weather and the Water Cycle'),
